const http = require("http");
const fs = require("fs");
const path = require("path");
const { spawn } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const ACCOUNT = "0123456789abcdef0123456789abcdef";
const NAME = "ludion-new-worker";
const seen = [];
const notFound = (res) => { res.writeHead(404, { "content-type": "application/json" }); res.end(JSON.stringify({ success: false, errors: [{ code: 10007, message: "not found" }], messages: [], result: null })); };
const server = http.createServer((req, res) => {
  let body = "";
  req.on("data", (c) => { body += c; });
  req.on("end", () => {
    const p = req.url.split("?")[0].replace(/^\/client\/v4/, "");
    seen.push(req.method + " " + p);
    if (req.method === "GET" && p === "/accounts/" + ACCOUNT + "/workers/services/" + NAME) return notFound(res);
    if (req.method === "GET" && p === "/accounts/" + ACCOUNT + "/workers/subdomain") return notFound(res);
    if (req.method === "PUT" && p.startsWith("/accounts/" + ACCOUNT + "/workers/scripts/" + NAME)) {
      res.writeHead(400, { "content-type": "application/json" });
      return res.end(JSON.stringify({ success: false, errors: [{ code: 10063, message: "You need a workers.dev subdomain in order to proceed." }], messages: [], result: null }));
    }
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ success: true, errors: [], messages: [], result: {} }));
  });
});
server.listen(0, "127.0.0.1", () => {
  const port = server.address().port;
  const dir = fs.mkdtempSync("/tmp/proj-");
  fs.writeFileSync(path.join(dir, "index.js"), "export default { fetch() { return new Response('hi'); } };\n");
  const env = { ...process.env, CLOUDFLARE_API_BASE_URL: "http://127.0.0.1:" + port + "/client/v4", CLOUDFLARE_API_TOKEN: "test-token", CLOUDFLARE_ACCOUNT_ID: ACCOUNT, WRANGLER_SEND_METRICS: "false", CI: "true", NO_PROXY: "*", HTTP_PROXY: "", HTTPS_PROXY: "" };
  // wrangler deploy of a brand-new Worker on an account with no workers.dev subdomain
  const child = spawn(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "deploy", "index.js", "--name", NAME, "--compatibility-date", "2025-01-01", "--no-bundle"], { cwd: dir, env, stdio: ["ignore", "pipe", "pipe"] });
  let out = "";
  child.stdout.on("data", (d) => { out += d; });
  child.stderr.on("data", (d) => { out += d; });
  const timer = setTimeout(() => { child.kill("SIGKILL"); broken("wrangler deploy timed out; requests: " + seen.join(", ")); }, 75000);
  child.on("close", (code) => {
    clearTimeout(timer);
    server.close();
    const sub = seen.indexOf("GET /accounts/" + ACCOUNT + "/workers/subdomain");
    const up = seen.findIndex((s) => s.startsWith("PUT /accounts/" + ACCOUNT + "/workers/scripts/" + NAME));
    if (up >= 0 && (sub < 0 || sub > up)) symptom("wrangler deploy uploaded the new Worker before checking for a workers.dev subdomain");
    if (sub < 0) broken("wrangler deploy never reached the workers.dev subdomain check; exit " + code + "; requests: " + seen.join(", ") + "\n" + out.slice(-2000));
    if (up >= 0) broken("upload still sent after the subdomain check failed; requests: " + seen.join(", "));
    if (code === 0) broken("wrangler deploy succeeded without a workers.dev subdomain");
    if (!out.includes("register a workers.dev subdomain")) broken("no registration message in output:\n" + out.slice(-2000));
    console.log("OK: wrangler deploy checked the workers.dev subdomain before uploading and stopped with a registration message");
    process.exit(0);
  });
});

